        await poslat(bot, chat_id,
                     "<b>Подбор под заказ из Кореи</b>\n<i>Шаг 1 из 3 · бюджет</i>\n\n"
                     "Сколько готовы вложить под ключ в Киеве?",
                     [[(b, "v_pb1:%d" % i)] for i, b in enumerate(BYUDZHET)])
        return
    if "kuzov" not in dannye:
        _podbor[kto] = dannye
        await poslat(bot, chat_id,
                     "<b>Подбор под заказ из Кореи</b>\n<i>Шаг 2 из 3 · кузов</i>\n\n"
                     "Бюджет: %s" % dannye["byudzhet"],
                     [[(k, "v_pb2:%d" % i)] for i, k in enumerate(KUZOV)])
        return
    _podbor[kto] = dannye
    await poslat(bot, chat_id,
                 "<b>Подбор под заказ из Кореи</b>\n<i>Шаг 3 из 3 · как связаться</i>\n\n"
                 "Бюджет: %s\nКузов: %s\n\n"
